def find_near_full_seps(r_s, r_e, c_s, c_e, grid, sep=2, threshold=0.8):
    """Find rows that are mostly sep (>= threshold)"""
    h_seps = []
    for r in range(r_s, r_e):
        row_vals = [grid[r][c] for c in range(c_s, c_e)]
        sep_count = sum(1 for v in row_vals if v == sep)
        if sep_count / len(row_vals) >= threshold:
            h_seps.append((r, sep_count, len(row_vals)))
    v_seps = []
    for c in range(c_s, c_e):
        col_vals = [grid[r][c] for r in range(r_s, r_e)]
        sep_count = sum(1 for v in col_vals if v == sep)
        if sep_count / len(col_vals) >= threshold:
            v_seps.append((c, sep_count, len(col_vals)))
    return h_seps, v_seps

